#include <iostream>

int main() {
    const int capacity = 8;
    int values[capacity] = {10, 20, 30, 40};
    int length = 4;

    // 输入 2，输出 30。
    int index = 0;
    std::cin >> index;
    if (std::cin.fail()) {
        std::cout << "请输入一个整数下标。\n";
        return 1;
    }

    if (index < 0 || index >= length) {
        std::cout << "读取失败：下标超出范围。\n";
        return 1;
    }

    std::cout << values[index] << '\n';
    return 0;
}
